"""Prepare six pinned, public-domain reference work spans for P-J-011."""
import hashlib
import json
from pathlib import Path
import re

from vs import path, refcorpus


WORKS = {
    "la_augustine": {
        "work": "Augustine, Confessiones, Books I–II",
        "start": "1. _Magnus es, Domine",
        "stop": "\nLIBER TERTIUS.",
        "cleaning": "Remove inline square-bracketed sidenotes and footnote calls, braced page numbers, and four-space-indented editorial summaries.",
        "confidence": "High. Main prose of the first two books in the 1838 Latin edition. Augustine’s own Biblical quotations remain.",
    },
    "la_vulg_daniel": {
        "work": "Clementine Vulgate, Daniel",
        "start": "\n1:1 Anno tertio",
        "stop": "\nPARALLELISMUS MEMBRORUM.",
        "cleaning": "Keep only blank-line-delimited paragraphs opening with a decimal chapter:verse token. The project normalizer removes the verse numbers.",
        "confidence": "High. The main verses only, independent of the English transcriber notes and Latin critical appendix. The Vulgate includes the Septuagint additions.",
    },
    "it_dante": {
        "work": "Dante, Commedia, Inferno",
        "start": "Nel mezzo del cammin di nostra vita",
        "stop": "\n  PURGATORIO",
        "cleaning": "Remove remaining Inferno canto-title lines. The raw pin contains the whole Commedia, while this span is Inferno only.",
        "confidence": "High. Starts at the first verse and ends after Inferno XXXIV.",
    },
    "it_villani": {
        "work": "Matteo Villani, Cronica, Book I",
        "start": "Esaminando nell’animo la vostra esortazione",
        "stop": "\nLIBRO SECONDO",
        "cleaning": "Keep the original author’s prologue and main Book I. Chapter headings remain. No modern introduction or table of contents.",
        "confidence": "High for main medieval prose. Chapter headings from the 1825 edition remain.",
    },
    "de_nibelunge": {
        "work": "Der Nibelunge liet, Middle High German text",
        "start": "Uns ist in alten mæren",
        "stop": None,
        "cleaning": "Drop letter-period-decimal manuscript and stanza tags, preserving the text of stanza and section headings. Use the text through its ending.",
        "confidence": "High. Gutenberg #48888 is Simrock’s Middle High German text. His modern German translation and editorial introduction are a different Gutenberg file (#14915).",
    },
    "de_walther": {
        "work": "Walther von der Vogelweide, Gedichte und Sprüche in Auswahl, poems",
        "start": "Uns hât der winter geschadet über al:",
        "stop": "\nANMERKUNGEN",
        "cleaning": "Omit all-uppercase section headings and bracket-initial editorial lines before the start of the commentary.",
        "confidence": "High. A single-author selection of lyric poetry independent of the Nibelungen epic. The modern notes are after the stop marker.",
    },
}
PAIRS = {
    "latin": {
        "train": "la_augustine",
        "evaluation": "la_vulg_daniel",
        "rationale": "Autobiographical theological prose versus an independent biblical book. Augustine’s own brief scriptural quotations are part of his work. No consecutive 12-word passage overlaps the selected Daniel edition.",
    },
    "italian": {
        "train": "it_dante",
        "evaluation": "it_villani",
        "rationale": "Dante’s narrative poem versus Matteo Villani’s historical chronicle. #426 used the same IDs, while these spans exclude Villani’s modern preface and reset the training and evaluation samples on actual medieval text.",
    },
    "german": {
        "train": "de_nibelunge",
        "evaluation": "de_walther",
        "rationale": "Anonymous heroic epic versus a selection of Walther’s lyrics and songs. Separate works and corpus editions, with no translation or anthology that contains the epic.",
    },
}


def sha256(s):
    return hashlib.sha256(s).hexdigest()


def extraction(cid, text):
    if cid == "la_augustine":
        return re.sub(r"\[[^\[\]]*\]|\{\d+\}|^    .*$", "", text, flags=re.M)
    if cid == "la_vulg_daniel":
        return "\n".join(p for p in text.split("\n\n") if re.match(r"^\d+:\d+ ", p.strip()))
    if cid == "it_dante":
        return re.sub(r"^\s*Inferno • Canto.*$", "", text, flags=re.M)
    if cid == "de_nibelunge":
        return re.sub(r"\s+[A-Z][.]\d+(?:[*a-z]?)", "", text)
    if cid == "de_walther":
        return "\n".join(line for line in text.splitlines()
                         if not (line.strip().isupper() or line.lstrip().startswith("[")))
    return text


def blocks(text):
    out, current, length = [], [], 0
    for word in text.split():
        current.append(word)
        length += len(word) + 1
        if length >= 400:
            out.append(" ".join(current))
            current, length = [], 0
    if current:
        out.append(" ".join(current))
    return out


def ngrams(text, n):
    words = text.split()
    return {tuple(words[i:i+n]) for i in range(len(words)-n+1)}


def main():
    refs = {e["id"]: e for e in refcorpus.pins()}
    archive, work_meta, texts = {}, {}, {}
    for cid, recipe in WORKS.items():
        e = refs[cid]
        source_file = Path(path(e["file"]))
        raw = source_file.read_bytes()
        assert sha256(raw) == e["sha256"], cid
        with source_file.open(encoding=e.get("encoding", "utf-8"), errors="replace") as src:
            stripped = refcorpus.strip_gutenberg(src.read())
        start = stripped.index(recipe["start"])
        stop = stripped.index(recipe["stop"], start + len(recipe["start"])) if recipe["stop"] else len(stripped)
        normalized = refcorpus.normalize(extraction(cid, stripped[start:stop]), e["lang"])
        texts[cid] = normalized
        archive[cid] = blocks(normalized)
        assert " ".join(archive[cid]) == normalized
        work_meta[cid] = {
            **recipe,
            "language": e["lang"],
            "catalog_period": e["period"],
            "raw_url": e["url"],
            "raw_sha256": e["sha256"],
            "catalog_url": f"https://www.gutenberg.org/ebooks/{e['gutenberg']}",
            "rights": "Project Gutenberg catalog marks public domain in the USA.",
            "encoding": e.get("encoding", "utf-8"),
            "span_start_stop": [start, stop],
            "normalized_symbols_including_spaces": len(normalized),
            "normalized_nonspace_symbols": len(normalized.replace(" ", "")),
            "blocks": len(archive[cid]),
            "sum_of_block_symbol_counts": sum(map(len, archive[cid])),
            "symbols_in_first_64_blocks": sum(map(len, archive[cid][:64])),
            "normalized_sha256": sha256(normalized.encode()),
            "newline_joined_blocks_sha256": sha256("\n".join(archive[cid]).encode()),
        }
    pair_meta = {lang: dict(pair) for lang, pair in PAIRS.items()}
    for lang, pair in pair_meta.items():
        a, b = pair["train"], pair["evaluation"]
        pair["exact_shared_blocks"] = len(set(archive[a]) & set(archive[b]))
        pair["exact_shared_distinct_12_word_windows"] = len(ngrams(texts[a], 12) & ngrams(texts[b], 12))
        assert not pair["exact_shared_blocks"]
    out = {
        "pairs": pair_meta,
        "works_by_corpus_id": work_meta,
        "extraction_order": "Decode the SHA-verified pinned file with universal newlines. Apply vs.refcorpus.strip_gutenberg. Find the literal start and stop markers, or use the end of the stripped file. Apply the listed per-work cleanup, then vs.refcorpus.normalize. Span offsets refer to the stripped decoded text before cleanup. Break at word boundaries once the same accounting as blocks_of reaches at least 400, keeping the final partial block. Counts including spaces treat each run of whitespace as one symbol.",
        "pr_426": {
            "url": "https://github.com/Ayan-Bandyopadhyay/voynich-swarm/pull/426",
            "design": "First 100 training-work blocks and 30 evaluation-work blocks built directly with refcorpus.blocks_of, using Augustine/Erasmus, Dante/Villani, Lucanor/Buen Amor and Chaucer/Paston. Order 0–8 smoothed character models and several reversible padding controls were used.",
            "editorial_confounds": "The pins start with editorial text in Augustine (1838 Latin Monitum), Erasmus (digital production and bilingual title line plus 20th-century transcriber corrections elsewhere), Villani (1825 editor address), Lucanor (editorial transcription note), Buen Amor (edition front matter and extensive notes), Chaucer (Purves’s table of contents and biography), and Paston (Gairdner’s early-20th-century critical edition’s preface and long historical introduction). These are risks for any claim about source-language coding rates from untrimmed beginnings.",
        },
    }
    dest = Path(__file__).parent
    (dest / "works.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (dest / "clean_works.json").write_text(json.dumps(archive, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps(pair_meta, ensure_ascii=False, indent=2))
    for cid, e in work_meta.items():
        print(cid, e["normalized_symbols_including_spaces"], e["normalized_nonspace_symbols"], e["blocks"], e["symbols_in_first_64_blocks"])


if __name__ == "__main__":
    main()

scripts.battery.py:
"""Character code lengths and sample entropy with train and evaluation works separated."""
from collections import Counter
from dataclasses import dataclass
from hashlib import sha256
import json
from math import isclose, log2
from pathlib import Path

MAX_ORDER = 8
PRIOR_STRENGTH = 2
PSEUDOCOUNT = 0.5
PAD_ALPHABETS = {
    'identity': '', 'substitution': '', 'addB': 'B',
    'matched_deterministic': 'BD', 'matched_random': 'BD', 'suffix_B': 'B',
}
SOURCE = 'abcdefghijklmnopqrstuvwxyz '


@dataclass
class Markov:
    alphabet: str
    counts: list
    totals: list

    @classmethod
    def fit(cls, blocks, alphabet, max_order=MAX_ORDER):
        counts = [dict() for _ in range(max_order + 1)]
        for block in blocks:
            if set(block) - set(alphabet):
                raise ValueError('training contains a symbol outside the declared alphabet')
            for i, symbol in enumerate(block):
                for order in range(min(i, max_order) + 1):
                    ctx = block[i-order:i]
                    table = counts[order].setdefault(ctx, Counter())
                    table[symbol] += 1
        if not counts[0]:
            raise ValueError('the training work is empty')
        totals = [{ctx: row.total() for ctx, row in table.items()} for table in counts]
        return cls(alphabet, counts, totals)

    def probabilities(self, symbol, context):
        if symbol not in self.alphabet:
            raise ValueError(f'evaluation contains a symbol outside the declared alphabet: {symbol!r}')
        cells = self.counts[0]['']
        prior = (cells[symbol] + PSEUDOCOUNT) / (self.totals[0][''] + PSEUDOCOUNT * len(self.alphabet))
        yield prior
        for order in range(1, len(self.counts)):
            if len(context) >= order:
                ctx = context[-order:]
                row = self.counts[order].get(ctx)
                if row is not None:
                    prior = (row[symbol] + PRIOR_STRENGTH * prior) / (self.totals[order][ctx] + PRIOR_STRENGTH)
            yield prior

    def bits(self, blocks):
        result = [0.0] * len(self.counts)
        for block in blocks:
            for i, symbol in enumerate(block):
                context = block[max(0, i-len(result)+1):i]
                for order, probability in enumerate(self.probabilities(symbol, context)):
                    result[order] -= log2(probability)
        return result


def sample_entropy_bits(blocks, max_order=MAX_ORDER):
    """Empirical conditional entropy, allowing shorter context at each block start."""
    histograms = [dict() for _ in range(max_order + 1)]
    for block in blocks:
        for i, symbol in enumerate(block):
            for order in range(max_order + 1):
                ctx = block[max(0, i-order):i]
                table = histograms[order].setdefault(ctx, Counter())
                table[symbol] += 1
    totals = []
    for order in range(max_order + 1):
        bits = 0.0
        for row in histograms[order].values():
            total = row.total()
            bits -= sum(n * log2(n / total) for n in row.values())
        totals.append(bits)
    return totals


def adjacent_entropy(blocks):
    pairs = {}
    for block in blocks:
        for left, right in zip(block, block[1:]):
            pairs.setdefault(left, Counter())[right] += 1
    transitions, bits = 0, 0.0
    for row in pairs.values():
        count = row.total()
        transitions += count
        bits -= sum(n * log2(n/count) for n in row.values())
    return {'transitions': transitions,
            'bits_per_transition': round(bits/transitions, 8) if transitions else None}


def digest(text):
    return sha256(text.encode()).hexdigest()


def evaluate(train, test, kinds, encode, decode, side_bits):
    train_text = '\n'.join(train)
    test_text = '\n'.join(test)
    source_count = sum(map(len, test))
    if not source_count or not sum(map(len, train)):
        raise ValueError('both disjoint works must have nonempty normalised blocks')
    hashes_train = {digest(block) for block in train}
    hashes_test = {digest(block) for block in test}
    if hashes_train & hashes_test:
        raise ValueError('an exact normalised block occurs in both works')

    identity = Markov.fit(train, SOURCE).bits(test)
    result = {}
    for kind in kinds:
        encoded_train = encode(train_text, kind, seed=40801)
        encoded_test = encode(test_text, kind, seed=40802)
        assert decode(encoded_train, kind) == train_text
        assert decode(encoded_test, kind) == test_text
        train_blocks = encoded_train.split('\n')
        test_blocks = encoded_test.split('\n')
        assert len(train_blocks) == len(train) and len(test_blocks) == len(test)
        assert [text.count(' ') for text in train_blocks] == [text.count(' ') for text in train]
        assert [text.count(' ') for text in test_blocks] == [text.count(' ') for text in test]
        if kind == 'matched_random':
            for raw, encoded in ((train_text, encoded_train), (test_text, encoded_test)):
                ordered_pads = (ch for ch in encoded if ch in 'BD')
                reconstructed = ''.join(ch if ch in ' \n' else ch + next(ordered_pads) for ch in raw)
                assert reconstructed == encoded and next(ordered_pads, None) is None
        output_count = sum(map(len, test_blocks))
        alphabet = SOURCE + PAD_ALPHABETS[kind]
        forward = Markov.fit(train_blocks, alphabet).bits(test_blocks)
        empirical = sample_entropy_bits(test_blocks)
        side = side_bits(test_text, kind)
        inverse = [raw + side for raw in identity]
        rows = []
        for order, (a, b, c) in enumerate(zip(forward, empirical, inverse)):
            assert isclose((a/source_count) * source_count, (a/output_count) * output_count)
            rows.append({'order': order, 'forward_bits': round(a, 6),
                         'forward_bits_per_source': round(a/source_count, 8),
                         'forward_bits_per_output': round(a/output_count, 8),
                         'empirical_bits_per_source': round(b/source_count, 8),
                         'empirical_bits_per_output': round(b/output_count, 8),
                         'inverse_bits': round(c, 6),
                         'inverse_bits_per_source': round(c/source_count, 8),
                         'inverse_bits_per_output': round(c/output_count, 8)})
        result[kind] = {'output_symbols': output_count, 'output_train_symbols': sum(map(len, train_blocks)),
                        'output_checksum': digest(encoded_test), 'train_output_checksum': digest(encoded_train),
                        'side_bits': round(side, 6), 'orders': rows,
                        'adjacent_empirical': adjacent_entropy(test_blocks),
                        'training_marker_counts': dict(Counter(ch for ch in encoded_train if ch in 'BD')),
                        'evaluation_marker_counts': dict(Counter(ch for ch in encoded_test if ch in 'BD'))}
        if kind in ('identity', 'substitution'):
            assert all(isclose(raw, transformed, rel_tol=1e-11) for raw, transformed in zip(identity, forward))
    a = result['matched_deterministic']
    b = result['matched_random']
    assert a['output_symbols'] == b['output_symbols']
    assert a['output_train_symbols'] == b['output_train_symbols']
    assert a['training_marker_counts'] == b['training_marker_counts']
    assert a['evaluation_marker_counts'] == b['evaluation_marker_counts']
    return {'train_blocks': len(train), 'eval_blocks': len(test), 'train_symbols': sum(map(len, train)),
            'eval_source_symbols': source_count, 'train_source_checksum': digest(train_text),
            'eval_source_checksum': digest(test_text), 'eval_spaces': test_text.count(' '),
            'exact_block_overlap': 0, 'modes': result}


def main():
    from transforms import KINDS, encode, decode, side_bits

    base = Path(__file__).resolve().parent
    works = json.loads((base/'clean_works.json').read_text())
    selection = json.loads((base/'works.json').read_text())
    output = {}
    for name, pair in selection['pairs'].items():
        train_id, test_id = pair['train'], pair['evaluation']
        assert train_id != test_id and len(works[train_id]) >= 64 and len(works[test_id]) >= 64
        print('Scoring', name, 'independent', train_id, '->', test_id, flush=True)
        output[name] = evaluate(works[train_id][:64], works[test_id][:64], KINDS, encode, decode, side_bits)
        output[name]['work_metadata'] = pair
        for mode, result in output[name]['modes'].items():
            last = result['orders'][-1]
            print(mode, 'output', result['output_symbols'], 'source', last['forward_bits_per_source'],
                  'output_rate', last['forward_bits_per_output'], 'inverse', last['inverse_bits_per_source'], flush=True)
        (base/'results.json').write_text(json.dumps(output, ensure_ascii=False, indent=2)+'\n')


if __name__ == '__main__':
    main()
